def copy_random_list(head):
    if not head:
        return None
    cur = head                         # 1. interleave: A → A' → B → B'
    while cur:
        cur.next = Node(cur.val, cur.next)
        cur = cur.next.next
    cur = head                         # 2. wire randoms: A'.random = A.random'
    while cur:
        if cur.random:
            cur.next.random = cur.random.next
        cur = cur.next.next
    cur, copy_head = head, head.next   # 3. split the two lists apart
    while cur:
        copy = cur.next
        cur.next = copy.next
        copy.next = copy.next.next if copy.next else None
        cur = cur.next
    return copy_head
